<?php require_once __DIR__.'/functions.php';require_once __DIR__.'/app_init.php';require_login();$pdo=dogvive_db();$uid=dogvive_user_id();if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['leida'])){$q=$pdo->prepare('UPDATE notificacion SET Estado="Leida" WHERE id_notificacion=? AND id_usuario=?');$q->execute([(int)$_POST['leida'],$uid]);header('Location: '.base_url().'/notificaciones.php');exit;}if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['todas'])){$q=$pdo->prepare('UPDATE notificacion SET Estado="Leida" WHERE id_usuario=?');$q->execute([$uid]);header('Location: '.base_url().'/notificaciones.php');exit;}$q=$pdo->prepare('SELECT * FROM notificacion WHERE id_usuario=? ORDER BY Fecha DESC,Hora DESC,id_notificacion DESC');$q->execute([$uid]);$rows=$q->fetchAll();$unread=count(array_filter($rows,fn($n)=>strtolower((string)$n['Estado'])!=='leida'));start_app('Notificaciones','notificaciones');page_wrap_start('Notificaciones',$unread.' sin leer');if($rows): ?><form method="post" style="margin-bottom:16px"><button class="btn btn-secondary" name="todas" value="1">Marcar todas como leídas</button></form><div class="card" style="padding:0"><?php foreach($rows as $n): ?><div class="notification <?= strtolower((string)$n['Estado'])!=='leida'?'unread':'' ?>"><div class="stat-icon">🔔</div><div class="grow"><strong><?= e((string)$n['Tipo']) ?></strong><p class="muted"><?= e((string)$n['Contenido']) ?></p><small class="muted"><?= e((string)$n['Fecha']) ?> <?= e(substr((string)$n['Hora'],0,5)) ?> · <?= e((string)$n['Estado']) ?></small><?php if($n['Enlace']): ?><a href="<?= e(base_url().'/'.ltrim((string)$n['Enlace'],'/')) ?>">Abrir</a><?php endif; ?></div><?php if(strtolower((string)$n['Estado'])!=='leida'): ?><form method="post"><button class="btn btn-secondary" name="leida" value="<?= (int)$n['id_notificacion'] ?>">Marcar leída</button></form><?php endif; ?></div><?php endforeach; ?></div><?php else: ?><div class="card">Todavía no tienes notificaciones.</div><?php endif; page_wrap_end();end_app();
